from __future__ import annotations

import json
import math
from pathlib import Path

import numpy as np

from .build_source import load_local_tskit


TASK_DIR = Path(__file__).resolve().parents[1]
FIXTURE_DIR = TASK_DIR / "fixtures"
OUTPUT_DIR = TASK_DIR / "outputs"
EXPORTS = (
    ("export_a", FIXTURE_DIR / "cohort_export_a.trees"),
    ("export_b", FIXTURE_DIR / "cohort_export_b.trees"),
)


def _epochs(values: list[object]) -> np.ndarray:
    parsed = [math.inf if value == "inf" else float(value) for value in values]
    epochs = np.asarray(parsed, dtype=float)
    if epochs.ndim != 1 or epochs.size < 3:
        raise ValueError("study epochs are invalid")
    if epochs[0] != 0.0 or not math.isinf(float(epochs[-1])):
        raise ValueError("study epochs must span sample age to infinity")
    if np.any(np.diff(epochs[:-1]) <= 0):
        raise ValueError("finite study epochs must be strictly increasing")
    return epochs


def _population_ids(ts, names: list[str]) -> list[int]:
    available: dict[str, int] = {}
    for population in ts.populations():
        metadata = population.metadata
        if isinstance(metadata, dict) and isinstance(metadata.get("name"), str):
            available[metadata["name"]] = population.id
    try:
        return [available[name] for name in names]
    except KeyError as exc:
        raise ValueError(
            f"archive does not contain configured population {exc.args[0]!r}"
        ) from exc


def _plain_floats(values: np.ndarray) -> list[object]:
    result: list[object] = []
    for value in np.asarray(values, dtype=float).reshape(-1):
        result.append(float(value) if math.isfinite(float(value)) else None)
    return result


def _weighted_tree_summary(ts) -> dict[str, float]:
    root_span = 0.0
    root_time_span = 0.0
    for tree in ts.trees():
        span = float(tree.span)
        roots = list(tree.roots)
        root_span += span * len(roots)
        if roots:
            root_time_span += span * float(np.mean([tree.time(root) for root in roots]))
    return {
        "mean_roots": root_span / float(ts.sequence_length),
        "mean_root_time_generations": root_time_span / float(ts.sequence_length),
    }


def run_cohort_study(archive_path: Path, output_name: str) -> dict[str, object]:
    tskit = load_local_tskit()
    config = json.loads(
        (FIXTURE_DIR / "analysis_config.json").read_text(encoding="utf-8")
    )
    ts = tskit.load(archive_path)

    population_names = [str(value) for value in config["population_names"]]
    population_ids = _population_ids(ts, population_names)
    sample_sets = [ts.samples(population=value) for value in population_ids]
    if any(samples.size == 0 for samples in sample_sets):
        raise ValueError("configured population has no samples")

    epochs = _epochs(list(config["epochs_generations"]))
    comparisons = [tuple(int(value) for value in pair) for pair in config["comparisons"]]
    comparison_labels = [
        f"{population_names[left]}:{population_names[right]}"
        for left, right in comparisons
    ]

    branch_diversity = ts.diversity(sample_sets=sample_sets, mode="branch")
    branch_divergence = ts.divergence(
        sample_sets=sample_sets,
        indexes=comparisons,
        mode="branch",
    )
    demographic_profile = ts.pair_coalescence_rates(
        epochs,
        sample_sets=sample_sets,
        indexes=comparisons,
    )
    if demographic_profile.shape != (len(comparisons), epochs.size - 1):
        raise RuntimeError(
            f"unexpected cohort profile shape: {demographic_profile.shape}"
        )
    finite_profile = np.isfinite(demographic_profile[:, :-1]).all()
    if not finite_profile:
        raise RuntimeError("cohort analysis returned non-finite finite-epoch values")

    tree_summary = _weighted_tree_summary(ts)
    report: dict[str, object] = {
        "schema_version": "1.0",
        "archive": {
            "samples": int(ts.num_samples),
            "populations": len(sample_sets),
            "nodes": int(ts.num_nodes),
            "edges": int(ts.num_edges),
            "marginal_trees": int(ts.num_trees),
            "coordinate_extent": float(ts.sequence_length),
        },
        "genealogy_qc": {
            **tree_summary,
            "branch_diversity": _plain_floats(branch_diversity),
            "branch_divergence": _plain_floats(branch_divergence),
        },
        "cohort_history": {
            "comparisons": comparison_labels,
            "epoch_breaks_generations": [
                float(value) if math.isfinite(float(value)) else None for value in epochs
            ],
            "profiles": [
                _plain_floats(demographic_profile[index])
                for index in range(len(comparisons))
            ],
        },
    }

    OUTPUT_DIR.mkdir(exist_ok=True)
    (OUTPUT_DIR / output_name).write_text(
        json.dumps(report, indent=2, sort_keys=True, allow_nan=False) + "\n",
        encoding="utf-8",
    )
    return report


def _profile_array(report: dict[str, object]) -> np.ndarray:
    cohort_history = report["cohort_history"]
    if not isinstance(cohort_history, dict):
        raise RuntimeError("cohort history is not a mapping")
    profiles = cohort_history.get("profiles")
    if not isinstance(profiles, list) or len(profiles) == 0:
        raise RuntimeError("cohort history contains no profiles")
    return np.asarray(
        [
            [math.nan if value is None else float(value) for value in row]
            for row in profiles
        ],
        dtype=float,
    )


def run_archive_audit() -> dict[str, object]:
    reports: dict[str, dict[str, object]] = {}
    for label, archive_path in EXPORTS:
        reports[label] = run_cohort_study(
            archive_path,
            output_name=f"{label}_cohort_study.json",
        )

    first = _profile_array(reports["export_a"])
    second = _profile_array(reports["export_b"])
    if first.shape != second.shape:
        raise RuntimeError("cohort profile shapes differ")
    finite = np.isfinite(first) & np.isfinite(second)
    if not np.any(finite):
        raise RuntimeError("cohort audit produced no comparable finite values")
    differences = np.abs(first[finite] - second[finite])

    summary: dict[str, object] = {
        "schema_version": "1.0",
        "exports": [
            {
                "label": label,
                "archive": archive_path.name,
                "study_record": f"outputs/{label}_cohort_study.json",
            }
            for label, archive_path in EXPORTS
        ],
        "population_history_observation": {
            "profile_shape": list(first.shape),
            "finite_values_compared": int(np.sum(finite)),
            "nonfinite_pattern_match": bool(
                np.array_equal(np.isfinite(first), np.isfinite(second))
            ),
            "maximum_absolute_difference": float(np.max(differences)),
            "mean_absolute_difference": float(np.mean(differences)),
        },
    }
    OUTPUT_DIR.mkdir(exist_ok=True)
    (OUTPUT_DIR / "archive_audit_summary.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True, allow_nan=False) + "\n",
        encoding="utf-8",
    )
    return summary

