/* The pair-coalescence statistics are estimated over the sequence actually
 * occupied by the genealogies. If the tree sequence contains windows without
 * edges (null trees, which are valid parts of a sequence), those windows
 * carry no genealogical mass and must not dilute the span normalisation.
 * Compute the span of non-missing (edge covered) sequence in each window so
 * that the results are invariant to the presence of such empty regions. */
if (options & TSK_STAT_SPAN_NORMALISE) {
    num_edges = tables->edges.num_rows;
    left_order = tables->indexes.edge_insertion_order;
    window_non_missing_span = tsk_calloc(num_windows, sizeof(*window_non_missing_span));
    if (window_non_missing_span == NULL) {
        ret = TSK_ERR_NO_MEMORY;
        goto out;
    }
    for (w = 0; w < (tsk_id_t) num_windows; w++) {
        /* Length of the union of edge intervals clipped to this window,
         * i.e. the span of non-missing sequence. Edges are visited in
         * left-to-right order, so the clamped left endpoints are
         * non-decreasing and a single merge sweep is sufficient. */
        double covered_span = 0.0;
        cur_left = 0.0;
        cur_right = 0.0;
        has_interval = false;
        for (e = 0; e < (tsk_id_t) num_edges; e++) {
            const tsk_id_t edge_id = left_order[e];
            eleft = tables->edges.left[edge_id];
            eright = tables->edges.right[edge_id];
            if (eright <= windows[w] || eleft >= windows[w + 1]) {
                continue;
            }
            if (eleft < windows[w]) {
                eleft = windows[w];
            }
            if (eright > windows[w + 1]) {
                eright = windows[w + 1];
            }
            if (!has_interval) {
                cur_left = eleft;
                cur_right = eright;
                has_interval = true;
            } else if (eleft <= cur_right) {
                if (eright > cur_right) {
                    cur_right = eright;
                }
            } else {
                covered_span += cur_right - cur_left;
                cur_left = eleft;
                cur_right = eright;
            }
        }
        if (has_interval) {
            covered_span += cur_right - cur_left;
        }
        window_non_missing_span[w] = covered_span;
    }
}

