/* The pair-coalescence statistics are estimated over the sequence actually
 * occupied by the genealogies. If the tree sequence contains windows without
 * edges (null trees, which are valid parts of a sequence), those windows
 * carry no genealogical mass and must not dilute the span normalisation.
 * Compute the span of non-missing (edge covered) sequence in each window so
 * that the results are invariant to the presence of such empty regions.
 *
 * We first reduce the (left-sorted) edge intervals to their union, then
 * distribute each disjoint covered segment across the (contiguous) windows
 * it overlaps. Both sweeps are linear, so this is O(num_edges + num_windows).
 */
if (options & TSK_STAT_SPAN_NORMALISE) {
    num_edges = tables->edges.num_rows;
    left_order = tables->indexes.edge_insertion_order;
    window_non_missing_span = tsk_calloc(num_windows, sizeof(*window_non_missing_span));
    covered_left = tsk_malloc((num_edges + 1) * sizeof(*covered_left));
    covered_right = tsk_malloc((num_edges + 1) * sizeof(*covered_right));
    if (window_non_missing_span == NULL || covered_left == NULL
        || covered_right == NULL) {
        ret = TSK_ERR_NO_MEMORY;
        goto out;
    }
    /* Union of edge intervals (edges are in increasing-left order). */
    num_segments = 0;
    has_interval = false;
    for (e = 0; e < (tsk_id_t) num_edges; e++) {
        eleft = tables->edges.left[left_order[e]];
        eright = tables->edges.right[left_order[e]];
        if (!has_interval) {
            cur_left = eleft;
            cur_right = eright;
            has_interval = true;
        } else if (eleft <= cur_right) {
            if (eright > cur_right) {
                cur_right = eright;
            }
        } else {
            covered_left[num_segments] = cur_left;
            covered_right[num_segments] = cur_right;
            num_segments++;
            cur_left = eleft;
            cur_right = eright;
        }
    }
    if (has_interval) {
        covered_left[num_segments] = cur_left;
        covered_right[num_segments] = cur_right;
        num_segments++;
    }
    /* Distribute each disjoint covered segment over the windows it spans.
     * Both the segments and the windows are sorted, so the window cursor only
     * ever moves forward and each window is accumulated at most once. */
    w = 0;
    for (e = 0; e < (tsk_id_t) num_segments; e++) {
        eleft = covered_left[e];
        eright = covered_right[e];
        while (w < (tsk_id_t) num_windows && windows[w + 1] <= eleft) {
            w++;
        }
        for (; w < (tsk_id_t) num_windows && windows[w] < eright; w++) {
            double lo = (windows[w] > eleft) ? windows[w] : eleft;
            double hi = (windows[w + 1] < eright) ? windows[w + 1] : eright;
            if (hi > lo) {
                window_non_missing_span[w] += hi - lo;
            }
        }
    }
}

